import React, { useState, useRef, useCallback, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const videoRef = useRef(null);
  const streamRef = useRef(null);

  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState("🎥 Démarrage de la caméra...");
  const [result, setResult] = useState(null);

  // ================= CAMÉRA START =================
  useEffect(() => {
    const startCamera = async () => {
      try {
        setStatus("🎥 Démarrage de la caméra...");

        const mediaStream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "user", width: 1280, height: 720 }
        });

        streamRef.current = mediaStream;

        if (videoRef.current) {
          videoRef.current.srcObject = mediaStream;
        }

        setStatus("✅ Caméra démarrée avec succès");
        console.log("✅ Caméra OK");
      } catch (err) {
        console.error(err);
        setStatus("❌ Impossible d'accéder à la caméra");
      }
    };

    startCamera();

    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(t => t.stop());
      }
    };
  }, []);

  // ================= STOP CAMÉRA =================
  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(t => t.stop());
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setStatus("📴 Caméra arrêtée");
  };

  // ================= CAPTURE + RECOGNITION =================
  const handleCapture = useCallback(async () => {
    if (!videoRef.current) return;

    setLoading(true);
    setResult(null);

    try {
      // STEP 1
      setStatus("📸 Étape 1/4 : Capture de l'image...");
      console.log("STEP 1 - capture");

      const canvas = document.createElement("canvas");
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;

      const ctx = canvas.getContext("2d");
      ctx.drawImage(videoRef.current, 0, 0);

      const imageSrc = canvas.toDataURL("image/jpeg", 0.92);

      // STEP 2
      setStatus("🚀 Étape 2/4 : Envoi de l'image au Backend...");
      console.log("STEP 2 - send backend");

      const response = await attendanceAPI.recognize(imageSrc);

      // STEP 3
      setStatus("📥 Étape 3/4 : Réponse reçue du Backend...");
      console.log("STEP 3 - response:", response);

      const data = response?.data || response || {};

      // STEP 4 LOGIC
      const name =
        data.student ||
        data.student_name ||
        data.name ||
        "Inconnu";

      const confidence = Number(data.confidence || 0);

      if (data.success || data.student || confidence > 0) {
        const finalMsg = `✅ Étape 4/4 : Succès ! ${name} - Confiance ${(confidence * 100).toFixed(1)}%`;

        setStatus(finalMsg);

        setResult({
          name,
          confidence: (confidence * 100).toFixed(1),
          studentId: data.student_id || "N/A",
          time: new Date().toLocaleTimeString()
        });

      } else {
        setStatus(`⚠️ Étape 4/4 : ${data.message || "No face detected"}`);
      }

    } catch (err) {
      console.error(err);
      const msg =
        err?.response?.data?.error ||
        err?.message ||
        "Erreur serveur";

      setStatus(`❌ Étape 4/4 : ${msg}`);
    } finally {
      setLoading(false);
    }
  }, []);

  return (
    <div style={{ padding: 30, maxWidth: 800, margin: "auto", textAlign: "center" }}>

      <h2>📷 Reconnaissance Faciale</h2>

      {/* VIDEO */}
      <div style={{
        background: "#000",
        borderRadius: 12,
        overflow: "hidden",
        marginBottom: 20
      }}>
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          style={{ width: "100%" }}
        />
      </div>

      {/* BUTTONS */}
      <div style={{ display: "flex", gap: 10 }}>
        <button
          onClick={handleCapture}
          disabled={loading}
          style={{
            flex: 1,
            padding: 15,
            background: loading ? "#999" : "#4F46E5",
            color: "white",
            border: 0,
            borderRadius: 10,
            cursor: loading ? "not-allowed" : "pointer"
          }}
        >
          {loading ? "⏳ Analyse..." : "🔍 Capturer & Analyser"}
        </button>

        <button
          onClick={stopCamera}
          style={{
            flex: 1,
            padding: 15,
            background: "#EF4444",
            color: "white",
            border: 0,
            borderRadius: 10
          }}
        >
          🛑 Stop
        </button>
      </div>

      {/* STATUS */}
      <div style={{
        marginTop: 20,
        padding: 20,
        borderRadius: 10,
        background: status.includes("✅") ? "#DCFCE7" :
                    status.includes("⚠️") ? "#FEF9C3" : "#FEE2E2",
        color: "#111",
        fontWeight: 600
      }}>
        {status}
      </div>

      {/* RESULT */}
      {result && (
        <div style={{
          marginTop: 20,
          padding: 15,
          background: "#E0E7FF",
          borderRadius: 10
        }}>
          <p><b>👤 Nom:</b> {result.name}</p>
          <p><b>🎯 Confiance:</b> {result.confidence}%</p>
          <p><b>🆔 ID:</b> {result.studentId}</p>
          <p><b>🕒 Heure:</b> {result.time}</p>
        </div>
      )}

    </div>
  );
};

export default CameraRecognition;
